%[text] # **Laterally loaded tapered support structure (Quad plane element)**
%[text] A tapered cantilever is modeled with plane-stress quadrilateral elements and checked against the published benchmark. Mesh density and the locations used to extract displacement and stress are part of the verification.
%[text] **See** [Laterally loaded tapered support structure — PyMAPDL Examples](https://examples.mapdl.docs.pyansys.com/verif-manual/vm-005-laterally_loaded_tapered_support_structure.html#laterally-loaded-tapered-support-structure)
%[text] \![\](../utils/verify-quad-beam.png)
clear; clc;

%% Get OpenSeesMatlab instance
opsMAT = OpenSeesMatlab();
ops = opsMAT.opensees;
%[text] ### FE Model

%% Clean model
ops.wipe();
ops.model('basic', '-ndm', 2, '-ndf', 2);

%% Material and thickness
E  = 30e6;    % psi
nu = 0.0;
t  = 2.0;     % in

matTag = 1;
ops.nDMaterial('ElasticIsotropic', matTag, E, nu);

%% Mesh control
nElem = 100;          % number of quad elements along the beam length
nNodePerEdge = nElem + 1;

%% Geometry
% Top edge:    from (25,  0) to (75,  0)
% Bottom edge: from (25, -3) to (75, -9)

xTop = linspace(25, 75, nNodePerEdge);
yTop = zeros(1, nNodePerEdge);

xBot = linspace(25, 75, nNodePerEdge);
yBot = linspace(-3, -9, nNodePerEdge);

% Node numbering:
% top    : 1 ~ nNodePerEdge
% bottom : nNodePerEdge+1 ~ 2*nNodePerEdge

for i = 1:nNodePerEdge
    ops.node(i, xTop(i), yTop(i));
end

for i = 1:nNodePerEdge
    ops.node(nNodePerEdge + i, xBot(i), yBot(i));
end

%% Elements
% Counterclockwise ordering:
% [bottom-left, bottom-right, top-right, top-left]

conn = zeros(nElem, 4);

for e = 1:nElem
    nBL = nNodePerEdge + e;
    nBR = nNodePerEdge + e + 1;
    nTR = e + 1;
    nTL = e;

    conn(e, :) = [nBL, nBR, nTR, nTL];

    ops.element('quad', e, nBL, nBR, nTR, nTL, t, 'PlaneStress', matTag);
end

%% Boundary conditions
% Fixed end at x = 75 -> top last node and bottom last node
topFixed = nNodePerEdge;
botFixed = 2 * nNodePerEdge;

ops.fix(topFixed, 1, 1);
ops.fix(botFixed, 1, 1);

%% Load
% Concentrated vertical load at top-left node
ops.timeSeries('Linear', 1);
ops.pattern('Plain', 1, 1);
ops.load(1, 0.0, -4000.0);
%[text] ### Plot Model
opts = opsMAT.vis.defaultPlotModelOptions;
opts.nodes.showLabels = false;
opts.elements.showLabels = false;
opts.loads.showNodal = true;
opsMAT.vis.plotModel(opts=opts); %[output:43a2a5f9] %[output:8a280f60]
grid off %[output:8a280f60]
%%
%[text] ## Analysis setup
Nsteps = 2;
ops.constraints('Plain');
ops.numberer('RCM');
ops.system('BandGeneral');
ops.test('NormDispIncr', 1.0e-12, 50);
ops.algorithm('Newton');
ops.integrator('LoadControl', 1.0 / Nsteps);
ops.analysis('Static');
ODB = opsMAT.post.createODB("myODB", projectGaussToNodes="extrapolate");  % create ODB %[output:36197a01]
ok = ops.analyze(Nsteps);
% ODB.close();
%[text] ### Post-processing
nodeResp = opsMAT.post.getNodalResponse("myODB");
opts = opsMAT.vis.defaultPlotNodalResponseOptions;
opts.fixed.show = true;
opts.surf.showEdges = false;
opts.deform.show = true;

opsMAT.vis.plotNodalResponse(nodeResp, respType="disp", stepIdx="absMax", respComponent="UY", opts=opts); %[output:3d8e51eb]
colormap("jet") %[output:3d8e51eb]
axis off %[output:3d8e51eb]
title("Displacement Along y-Direction") %[output:3d8e51eb]
planeResp = opsMAT.post.getElementResponse("myODB", eleType="Plane");
opsMAT.vis.plotContinuumResponse(planeResp, ... %[output:0ed305ec]
    respType="StressAtNode", respComponent="vonMises", opts=opts); %[output:0ed305ec]
axis equal %[output:0ed305ec]
grid off %[output:0ed305ec]
title("Von Mises Stress"); %[output:0ed305ec]
vm = planeResp.StressMeasureAtNode.vonMises;  % Von Mises
sxx = planeResp.StressAtNode.sxx;   % sxx

nodeTags = planeResp.nodeTags;
%[text] Find nodes closest to (75,0) and (50,0)
numNode = 2 * nNodePerEdge;
coords = zeros(numNode, 2);
for i = 1:nNodePerEdge
    coords(i, :) = [xTop(i), yTop(i)];
end
for i = 1:nNodePerEdge
    coords(nNodePerEdge + i, :) = [xBot(i), yBot(i)];
end

fixedNode = localFindNearestNode(coords, [75, 0]);
midNode   = localFindNearestNode(coords, [50, 0]);

fixedIdx = nodeTags == fixedNode;
midIdx = nodeTags == midNode;

% get stress
sxxFixed = sxx(:, fixedIdx);  % nStep * 1
vmMid = vm(:, midIdx);  % nStep * 1
mid_stress_osp = max(vmMid);
fixed_end_stress_osp = max(sxxFixed);
%% Reference values from ANSYS example
target_mid = 8333.0;  % theory value
target_end = 7407.0;

mapdl182_mid = 8163.66;  % only 6 elements
mapdl182_end = 7151.10;
%[text] The published ANSYS model uses only seven elements. Results from such a coarse mesh should be interpreted as a discretization study: compare the refined solution and monitor convergence rather than expecting element-by-element agreement.
fprintf([ ... %[output:group:17bd246e] %[output:9c2ec942]
    '\n' ... %[output:9c2ec942]
    '---------------- OpenSeesMatlab vs Reference ----------------\n' ... %[output:9c2ec942]
    '| %-18s | %-10s | %-15s | %-15s | %-8s |\n' ... %[output:9c2ec942]
    '| %-18s | %10.2f | %15.2f | %15.2f | %8.4f |\n' ... %[output:9c2ec942]
    '| %-18s | %10.2f | %15.2f | %15.2f | %8.4f |\n' ... %[output:9c2ec942]
    '-------------------------------------------------------------\n'], ... %[output:9c2ec942]
    'LABEL', 'TARGET', 'MAPDL PLANE182', 'OpenSeesMatlab', 'RATIO', ... %[output:9c2ec942]
    'mid VonMises', target_mid, mapdl182_mid, mid_stress_osp, mid_stress_osp / target_mid, ... %[output:9c2ec942]
    'end sigma_x', target_end, mapdl182_end, fixed_end_stress_osp, fixed_end_stress_osp / target_end); %[output:group:17bd246e] %[output:9c2ec942]
%%
%[text] Local function:
function nodeId = localFindNearestNode(coords, pt)
    d2 = (coords(:,1) - pt(1)).^2 + (coords(:,2) - pt(2)).^2;
    [~, nodeId] = min(d2);
end

%[text] ### Acceptance check
%[text] Track displacement and stress at the stated locations as the mesh is refined. The benchmark is satisfied by convergence toward the reference response, not by matching a coarse model element for element.

